select :'batch', (select id from public.learning_objects where swedish = $q$försäljningsvärde$q$ and part_of_speech = 'noun' and status <> 'retired'), 'word_forms', 'genus', (select form_value from public.word_forms where learning_object_id = (select id from public.learning_objects where swedish = $q$försäljningsvärde$q$ and part_of_speech = 'noun' and status <> 'retired') and form_type = 'genus'), $q$ett$q$, $q$pilot 2026-11-01 #102 noun forms as for värde (SALDO värde..nn.1)$q$
where (select id from public.learning_objects where swedish = $q$försäljningsvärde$q$ and part_of_speech = 'noun' and status <> 'retired') is not null and (select form_value from public.word_forms where learning_object_id = (select id from public.learning_objects where swedish = $q$försäljningsvärde$q$ and part_of_speech = 'noun' and status <> 'retired') and form_type = 'genus') is distinct from $q$ett$q$;
insert into public.word_forms (learning_object_id, form_type, form_value, sort_order) select (select id from public.learning_objects where swedish = $q$försäljningsvärde$q$ and part_of_speech = 'noun' and status <> 'retired'), 'genus', $q$ett$q$, 0 where (select id from public.learning_objects where swedish = $q$försäljningsvärde$q$ and part_of_speech = 'noun' and status <> 'retired') is not null
