where (select id from public.learning_objects where swedish = $q$pop$q$ and part_of_speech = 'noun' and status <> 'retired') is not null and (select form_value from public.word_forms where learning_object_id = (select id from public.learning_objects where swedish = $q$pop$q$ and part_of_speech = 'noun' and status <> 'retired') and form_type = 'singular_definite') is distinct from $q$popen$q$;
insert into public.word_forms (learning_object_id, form_type, form_value, sort_order) select (select id from public.learning_objects where swedish = $q$pop$q$ and part_of_speech = 'noun' and status <> 'retired'), 'singular_definite', $q$popen$q$, 0 where (select id from public.learning_objects where swedish = $q$pop$q$ and part_of_speech = 'noun' and status <> 'retired') is not null
on conflict (learning_object_id, form_type) do update set form_value = excluded.form_value, updated_at = now() where word_forms.form_value is distinct from excluded.form_value;

