-- AI form suggestions: applied where the stored form now equals a SALDO-confirmed suggestion, rejected where
-- SALDO confirms the stored form instead (bana, mat, timmer, underhåll, sned, pop plural).
update public.content_suggestions set status = 'rejected', reviewed_at = now() where status = 'pending' and id in (287, 288, 164, 127, 128, 121, 122, 71, 72, 185);
update public.content_suggestions set status = 'applied', reviewed_at = now() where status = 'pending';
commit;
